effect.shader:
/** Luminância ITU-R BT.709. */
float luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

void main() {
    vec2 tam = vec2(textureSize(inputImg, 0));
    float lado = max(cellSize, 1.0);
    vec2 grade = tam / lado;

    vec2 escalado = acScreenNorm * grade;
    vec2 i = floor(escalado);
    vec2 f = fract(escalado) - 0.5;

    // Cor e luma do CENTRO da célula (1 lookup por célula).
    vec2 uvDoCentro = (i + 0.5) / grade;
    vec3 corDaImagem = texture(inputImg, uvDoCentro).rgb;
    float L = luma(corDaImagem);

    // Quantiza a luma em `levels` patamares — o que vira a densidade do traço.
    int n = clamp(int(levels + 0.5), 2, 8);
    float Lq = floor(L * float(n)) / float(n - 1);
    Lq = clamp(Lq, 0.0, 1.0);

    // A marca: círculo cujo raio vem do Lq (claro = ponto grande, escuro = ponto pequeno).
    // Em Lq = 0 o círculo some; em Lq = 1 cobre quase a célula toda.
    float raio = Lq * 0.5;
    float d = length(f);
    float marca = 1.0 - smoothstep(raio - 0.05, raio + 0.05, d);

    vec3 corDoTraco = mix(inkColor.rgb, corDaImagem, useImageColor);
    vec4 fundo = vec4(bgColor.rgb, bgColor.a);
    vec4 traco = vec4(corDoTraco, inkColor.a);

    vec4 saida = mix(fundo, traco, marca);

    fragColor = saida;
}
